import path from "node:path";
import { createTypeScriptImportResolver } from "eslint-import-resolver-typescript";
import { getTsconfig } from "get-tsconfig";

//#region helpers/createAutoTypeScriptImportResolver.ts
const createAutoTypeScriptImportResolver = (options) => {
	if (options?.project) return createTypeScriptImportResolver({
		alwaysTryTypes: true,
		...options
	});
	const tsconfigCache = /* @__PURE__ */ new Map();
	const resolvers = /* @__PURE__ */ new Map();
	return {
		interfaceVersion: 3,
		name: "eslint-import-resolver-typescript/auto",
		resolve: (source, file) => {
			const tsconfigPath = getTsconfig(path.dirname(file), "tsconfig.json", tsconfigCache)?.path;
			const key = tsconfigPath ?? "";
			const resolver = resolvers.get(key) ?? createTypeScriptImportResolver({
				alwaysTryTypes: true,
				...options,
				...tsconfigPath ? { project: tsconfigPath } : null
			});
			resolvers.set(key, resolver);
			return resolver.resolve(source, file);
		}
	};
};

//#endregion
export { createAutoTypeScriptImportResolver };